<template><main class="auth-page"><router-link class="auth-brand" to="/"><b>华</b><span>华夏智游<small>HUAXIA INTELLIGENT JOURNEY</small></span></router-link><section class="auth-layout"><div class="auth-story"><span>WELCOME TO HUAXIA JOURNEY</span><h1>让每一次探索<br/>都有<strong>自己的印记</strong></h1><p>登录后，你可以保存感兴趣的文化故事，并在下一次回来时继续你的华夏漫游。</p><div><b>礼</b><b>艺</b><b>器</b></div></div><section class="auth-card"><template v-if="isLoggedIn"><span class="auth-kicker">MY ACCOUNT</span><div class="account-welcome"><b>{{ user.name.slice(0, 1) }}</b><div><h2>欢迎回来，{{ user.name }}</h2><p>{{ user.email }}</p></div></div><div class="account-note"><strong>文化旅人</strong><span>已解锁你的专属文化漫游入口</span></div><button class="auth-submit" @click="$router.push('/')">回到首页　→</button><button class="auth-text-button" @click="signOut">退出登录</button></template><template v-else><div class="auth-tabs"><button :class="{ active: mode === 'login' }" @click="switchMode('login')">登录</button><button :class="{ active: mode === 'register' }" @click="switchMode('register')">注册</button></div><div class="auth-heading"><span>{{ mode === 'login' ? 'WELCOME BACK' : 'CREATE YOUR ACCOUNT' }}</span><h2>{{ mode === 'login' ? '欢迎回来' : '成为文化旅人' }}</h2><p>{{ mode === 'login' ? '继续你的华夏文化探索。' : '创建一个账户，保存你的探索足迹。' }}</p></div><form @submit.prevent="submit"><label v-if="mode === 'register'">昵称<input v-model.trim="form.name" maxlength="12" placeholder="例如：小华同学" autocomplete="nickname" /></label><label>邮箱<input v-model.trim="form.email" type="email" placeholder="name@example.com" autocomplete="email" /></label><label>密码<input v-model="form.password" type="password" minlength="6" placeholder="至少 6 位字符" :autocomplete="mode === 'login' ? 'current-password' : 'new-password'" /></label><label v-if="mode === 'register'">确认密码<input v-model="form.confirm" type="password" placeholder="再次输入密码" autocomplete="new-password" /></label><p v-if="message" class="auth-message" :class="{ error: isError }">{{ message }}</p><button class="auth-submit" :disabled="loading">{{ loading ? '正在处理…' : mode === 'login' ? '登录并继续探索　→' : '注册并开始探索　→' }}</button></form><p class="auth-footnote">这是课程项目的本地演示账户系统，账户仅保存在当前浏览器。</p></template></section></section></main></template>
<script setup>
import { reactive, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '../stores/auth'
const router = useRouter(); const route = useRoute(); const auth = useAuthStore(); const { user, isLoggedIn } = storeToRefs(auth); const mode = ref('login'), loading = ref(false), message = ref(''), isError = ref(false); const form = reactive({ name: '', email: '', password: '', confirm: '' })
function switchMode(nextMode) { mode.value = nextMode; message.value = ''; form.password = ''; form.confirm = '' }
async function submit() { message.value = ''; isError.value = false; if (mode.value === 'register' && form.name.trim().length < 2) return fail('昵称至少需要 2 个字符。'); if (!/^\S+@\S+\.\S+$/.test(form.email)) return fail('请输入正确的邮箱地址。'); if (form.password.length < 6) return fail('密码至少需要 6 位字符。'); if (mode.value === 'register' && form.password !== form.confirm) return fail('两次输入的密码不一致。'); loading.value = true; try { if (mode.value === 'login') await auth.login(form); else await auth.register(form); message.value = mode.value === 'login' ? '登录成功，正在继续探索。' : '注册成功，欢迎成为文化旅人。'; ElMessage.success(message.value); const target = typeof route.query.redirect === 'string' ? route.query.redirect : '/'; setTimeout(() => router.push(target), 500) } catch (error) { fail(error.message) } finally { loading.value = false } }
function fail(text) { isError.value = true; message.value = text }
function signOut() { auth.logout(); mode.value = 'login'; message.value = ''; router.replace('/auth') }
</script>
